{
  "title": "三声铃的约定",
  "synopsis": "林岚与周野默契配合更换主板电容，成功修复广播站硬件。两人定下敲三声铜铃报平安的约定，但在准备敲铃验收时，因电压不稳与街坊催促被迫悬置。",
  "preview_blurb": "老街广播站的主板电容终于换好，三声铜铃的约定即将兑现，但验收前夕的电压波动却让一切戛然而止。",
  "scenes": [
    {
      "title": "暗格里的冷门备件",
      "location": "老街广播站工作台",
      "dramatic_goal": "在焊接主板的拉扯中展现林岚的专业与周野的笨拙，通过递送工具建立初步默契。",
      "lines": [
        {
          "kind": "sfx",
          "text": "电烙铁接触焊锡时尖锐的嗞啦声，伴随松香受热挥发的嘶嘶声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "主板电容击穿，这就是保险管发黑的原因。纸板拿开点，松香烟熏到眼睛了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎，好嘞。这破电容烧得真透，外头都鼓包了。零件箱里还有备用的吗？我找找看。"
        },
        {
          "kind": "sfx",
          "text": "翻找零件箱，金属碰撞，设备架剧烈摇晃。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎哟！架子要倒了！"
        },
        {
          "kind": "sfx",
          "text": "林岚一把扶住沉重的设备架，金属摩擦声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别乱翻，碰倒主板就全完了。"
        },
        {
          "kind": "sfx",
          "text": "工具包拉链声，暗格金属小盒打开。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "470微法，耐压25伏。把烙铁递给我。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "你连这种老型号的冷门备件，都随身带在工具包暗格里？给，小心烫。"
        }
      ]
    },
    {
      "title": "三声铃的约定",
      "location": "老街广播站工作台",
      "dramatic_goal": "通过递水与闲聊打破防备，确立敲铃报平安的约定，完成情感层面的双向治愈与破冰。",
      "lines": [
        {
          "kind": "sfx",
          "text": "焊接嗞啦声，万用表清脆的滴滴声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "焊点饱满，通路正常。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "辛苦了，喝口热水，手都烫红了。老街坊们天天盼着这喇叭响，前街李大爷连听戏的收音机都擦干净备好了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "等主板装回去，通电正常后，你先敲墙上那个老铜铃。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "敲铃？那铃铛不是挂在那当装饰的吗？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "敲三声，给街坊报平安，告诉他们设备修好了，然后再开麦说话。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "三声铃报平安……行，我郑重答应你。这第一声铃，我替你敲。"
        }
      ]
    },
    {
      "title": "悬置的验收",
      "location": "老街广播站工作台",
      "dramatic_goal": "硬件修复成功带来短暂喜悦，但外部催促与电压隐患迫使敲铃动作悬置，留下验收悬念。",
      "lines": [
        {
          "kind": "sfx",
          "text": "螺丝刀拧紧机箱，推闸咔哒声。喇叭传出清晰平稳的沙沙底噪。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "响了！底噪很干净，没杂音！我拿话筒试试音，跟老街坊们打个招呼。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "等一下，放下话筒。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "怎么了？街坊们都等着呢。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "规矩不能破。先敲三声铃，再说话。"
        },
        {
          "kind": "sfx",
          "text": "脚步声，周野走过去握住黄铜拉绳。窗外传来街坊大妈焦急的喊声（模糊人声）。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "李大妈在窗外催了，问是不是又出事了。"
        },
        {
          "kind": "sfx",
          "text": "周野手一顿，拉绳摩擦声停止。电压表指针剧烈摆动发出急促的咔哒声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "电压不稳，指针在剧烈跳。先别敲，等电压降下来再说。"
        }
      ]
    }
  ],
  "episode_summary": "林岚与周野在广播站工作台默契配合，林岚从暗格取出冷门备件更换了击穿的主板电容，周野则承担起递工具与后勤的角色。在等待测试的间隙，两人聊起街坊对广播的依赖，林岚主动提出修好后由周野敲三声老铜铃报平安的约定，周野郑重答应，两人关系彻底破冰。主板装回通电后底噪干净，维修成功，但在周野准备拉绳敲铃时，窗外街坊的催促与电压表指针的剧烈摆动迫使林岚紧急叫停，敲铃验收被迫悬置。",
  "ending_hook": "硬件修复成功，但敲铃报平安的约定因电压不稳和街坊催促被迫悬置，留下验收悬念。",
